param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'nullable-value-type-name-aliases-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture




function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}

$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$rows=[Collections.Generic.List[object]]::new()
for($index=0;$index -lt $plan.names.Count;$index++){foreach($throwOnError in $plan.throwOnError){foreach($ignoreCase in $plan.ignoreCase){$row=[ordered]@{index=$index;throwOnError=[bool]$throwOnError;ignoreCase=[bool]$ignoreCase;outcome='null';exception=$null;hResult=0;paramName=$null;typeName=$null;fullName=$null;assemblyQualifiedName=$null;name=$null;namespace=$null;isArray=$null;isByRef=$null;isPointer=$null;containsGenericParameters=$null;isGenericTypeDefinition=$null;fullRoundtrip=$null;assemblyRoundtrip=$null};try{$type=[Type]::GetType([string]$plan.names[$index],[bool]$throwOnError,[bool]$ignoreCase);if($null -ne $type){$row.outcome='type';$row.fullName=$type.FullName;$row.assemblyQualifiedName=$type.AssemblyQualifiedName;$row.name=$type.Name;$row.namespace=$type.Namespace;$row.isArray=$type.IsArray;$row.isByRef=$type.IsByRef;$row.isPointer=$type.IsPointer;$row.containsGenericParameters=$type.ContainsGenericParameters;$row.isGenericTypeDefinition=$type.IsGenericTypeDefinition;$row.fullRoundtrip=[object]::ReferenceEquals($type,[Type]::GetType($type.FullName,$true,$false));$row.assemblyRoundtrip=[object]::ReferenceEquals($type,[Type]::GetType($type.AssemblyQualifiedName,$true,$false))}}catch{$errorValue=$_.Exception;while($null -ne $errorValue.InnerException){$errorValue=$errorValue.InnerException};if($errorValue -isnot [TypeLoadException] -and $errorValue -isnot [ArgumentException]){throw};$row.outcome='error';$row.exception=$errorValue.GetType().FullName;$row.hResult=$errorValue.HResult;if($errorValue -is [TypeLoadException]){$row.typeName=$errorValue.TypeName};if($errorValue -is [ArgumentException]){$row.paramName=$errorValue.ParamName}};$rows.Add($row)}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS nullable type names: $($rows.Count) scenarios"
